            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "La curiosité n'est que vanité le plus souvent ; on ne veut savoir que pour en parler.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Rien n'est si important à l'homme que son état ; rien ne lui est si redoutable que l'éternité.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Que l'âme soit mortelle ou immortelle, il est indubitable que cela doit mettre une différence entière dans la morale.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Pourquoi une vierge ne peut-elle enfanter ? Une poule ne fait-elle pas des œufs sans coq ?", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Qui sait si cette autre moitié de la vie où nous pensons veiller n'est pas un autre sommeil un peu différent du premier, dont nous nous éveillons quand nous pensons dormir ?", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Vous auriez bientôt la foi si vous aviez quitté ces plaisirs.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "tout le malheur des hommes vient d'une seule chose, qui est de ne pas savoir demeurer en repos dans une chambre.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "l'homme est si malheureux qu'il s'ennuierait même sans aucune cause d'ennui par l'état propre de sa complexion.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Opinions du peuple saines. Le plus grand des maux est les guerres civiles. Elles sont sûres si on veut récompenser les mérites, car tous diront qu'ils méritent. Le mal à craindre d'un sot qui succède par droit de naissance n'est ni si grand, ni si sûr.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Soumission. Il faut savoir douter où il faut, assurer où il faut, en se soumettant où il faut. Qui ne fait pas ainsi n'entend pas la force de la raison. Il y en a qui faillent contre ces trois principes, ou en assurant tout comme démonstratif, manque de se connaître en démonstration, ou en doutant de tout, manque de savoir où il faut se soumettre, ou en se soumettant à tout, manque de savoir où il faut juger. Pyrrhonien, géomètre, chrétien : doute, assurance, soumission.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "La dernière démarche de la raison est de reconnaître qu'il y a une infinité de choses qui la surpassent. Elle n'est que faible si elle ne va jusqu'à connaître cela. Que si les choses naturelles la surpassent, que dira-t-on des surnaturelles ?", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "c'est une sphère infinie dont le centre est partout, la circonférence nulle part.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Que l'homme étant revenu à soi considère ce qu'il est au prix de ce qui est, qu'il se regarde comme égaré dans ce canton détourné de la nature ; et que de ce petit cachot où il se trouve logé, j'entends l'univers, il apprenne à estimer la terre, les royaumes, les villes, les maisons et soi-même son juste prix. Qu'est-ce qu'un homme, dans l'infini ?", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "On se croit naturellement bien plus capable d'arriver au centre des choses, que d'embrasser leur circonférence [...]", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Le nez de Cléopâtre, s'il eût été plus court, toute la face de la terre aurait changé.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Le cœur a ses raisons que la raison ne connaît point.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "La vraie éloquence se moque de l'éloquence, la vraie morale se moque de la morale [...].", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Tout notre raisonnement se réduit à céder au sentiment.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Le moi est haïssable.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "L'homme n'est ni ange, ni bête, et le malheur veut que qui veut faire l'ange fait la bête.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Nous ne cherchons jamais les choses, mais la recherche des choses.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "L'homme est si grand, que sa grandeur paraît même en ce qu'il se connaît misérable.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "L'homme n'est qu'un roseau le plus faible de la nature ; mais c'est un roseau pensant.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Ce sont deux excès également dangereux, d'exclure la raison, de n'admettre que la raison.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Ne pouvant fortifier la justice, on a justifié la force.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Le silence éternel de ces espaces infinis m'effraie.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Condition de l'homme : inconstance, ennui, inquiétude", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "C'est une étrange et longue guerre que celle où la violence essaie d'opprimer la vérité. Tous les efforts de la violence ne peuvent affaiblir la vérité, et ne servent qu'à la relever davantage. Toutes les lumières de la vérité ne peuvent rien pour arrêter la violence, et ne font que l'irriter encore plus. Quand la force combat la force, la plus puissante détruit la moindre ; quand on oppose les discours aux discours, ceux qui sont véritables et convaincants confondent et dissipent ceux qui n'ont que la vanité et le mensonge ; mais la violence et la vérité ne peuvent rien l'une sur l'autre. Qu'on ne prétende pas de là néanmoins que les choses soient égales : car il y a cette extrême différence que la violence n'a qu'un cours borné par l'ordre de Dieu qui en conduit les effets à la gloire de la vérité qu'elle attaque, au lieu que la vérité subsiste éternellement et triomphe enfin de ses ennemis ; parce qu'elle est éternelle et puissante comme Dieu même.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Je n'ai fait celle-ci plus longue que parce que je n'ai pas eu le loisir de la faire plus courte.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Il est question de savoir si la volonté de l'homme est la cause de la volonté de Dieu, ou la volonté de Dieu la cause de la volonté de l'homme.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Personne n’ignore qu’il y a deux entrées par où les opinions sont reçues dans l’âme, qui sont ses deux principales puissances, l’entendement et la volonté.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "N’entreprendre de définir aucune des choses tellement connues d’elles-meme, qu'on n'ait point de termes plus clairs pour les expliquer. N’admettre aucun des termes un peu obscurs ou équivoques, sans définition. N’employer dans la définition des termes que des mots parfaitement connus, ou déjà expliqués.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Qu'est ce que l'homme dans la nature ? Un néant à l'égard de l'infini, un tout à l'égard du néant, un milieu entre rien et tout.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "La chose la plus importante à la vie, c'est le choix du métier.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "Pesons le gain et la perte en prenant croix que Dieu est. Estimons ces deux cas : si vous gagnez, vous gagnez tout ; si vous perdez, vous ne perdez rien. Gagez donc qu'il est, sans hésiter.", Author = "Blaise Pascal" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_Pascal", Text = "J'ai découvert que tout le malheur des hommes vient d'une seule chose, qui est de ne pas savoir demeurer au repos dans une chambre.", Author = "Blaise Pascal" },
